import{_ as i,o as l,c as e,ag as t}from"./chunks/framework.Drp2S_UI.js";const u=JSON.parse('{"title":"开发调试工具","description":"","frontmatter":{},"headers":[],"relativePath":"guide/devtools.md","filePath":"guide/devtools.md","lastUpdated":1792653875000}'),o={name:"guide/devtools.md"};function s(r,a,d,n,h,c){return l(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="开发调试工具" tabindex="-1">开发调试工具 <a class="header-anchor" href="#开发调试工具" aria-label="Permalink to &quot;开发调试工具&quot;">​</a></h1><blockquote><p>此处链接指向上游外部插件；它们并非本 fork 维护的插件，需验证异步初始化、字体与 API 兼容性。</p></blockquote><p>Canvas Editor DevTools 是一个浏览器扩展插件，用于调试和分析 Canvas Editor 实例。</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>插件仓库地址：<a href="https://github.com/Hufe921/canvas-editor-devtools" target="_blank" rel="noreferrer">https://github.com/Hufe921/canvas-editor-devtools</a></p></div><h2 id="安装方式" tabindex="-1">安装方式 <a class="header-anchor" href="#安装方式" aria-label="Permalink to &quot;安装方式&quot;">​</a></h2><h3 id="开发模式安装" tabindex="-1">开发模式安装 <a class="header-anchor" href="#开发模式安装" aria-label="Permalink to &quot;开发模式安装&quot;">​</a></h3><ol><li>克隆或下载插件仓库代码</li><li>打开 Chrome 浏览器，访问 <code>chrome://extensions/</code></li><li>开启右上角的「开发者模式」</li><li>点击「加载已解压的扩展程序」按钮</li><li>选择插件项目文件夹</li></ol><h2 id="主要功能" tabindex="-1">主要功能 <a class="header-anchor" href="#主要功能" aria-label="Permalink to &quot;主要功能&quot;">​</a></h2><h3 id="元素树检查器" tabindex="-1">元素树检查器 <a class="header-anchor" href="#元素树检查器" aria-label="Permalink to &quot;元素树检查器&quot;">​</a></h3><ul><li>实时查看 Canvas Editor 文档结构</li><li>支持主内容区、页眉、页脚分区展示</li><li>点击元素查看详细的样式和属性信息</li><li>快速定位文档中的特定元素</li></ul><h3 id="事件监控器" tabindex="-1">事件监控器 <a class="header-anchor" href="#事件监控器" aria-label="Permalink to &quot;事件监控器&quot;">​</a></h3><p>实时监控以下类型的事件：</p><ul><li>内容变化事件</li><li>选区样式变化事件</li><li>页面事件</li><li>控件事件</li><li>图片事件</li><li>鼠标事件</li></ul><p>支持按事件类别筛选，自动滚动查看最新日志。</p><h3 id="配置面板" tabindex="-1">配置面板 <a class="header-anchor" href="#配置面板" aria-label="Permalink to &quot;配置面板&quot;">​</a></h3><ul><li>查看当前编辑器配置</li><li>修改外观、水印、页码等设置</li><li>调整表格样式、控件样式</li><li>配置光标相关选项</li></ul><h2 id="使用方法" tabindex="-1">使用方法 <a class="header-anchor" href="#使用方法" aria-label="Permalink to &quot;使用方法&quot;">​</a></h2><ol><li>打开使用 Canvas Editor 的网页</li><li>确保页面已将编辑器实例暴露到 <code>window.__CANVAS_EDITOR_INSTANCE__</code></li><li>按 F12 或右键选择「检查」打开开发者工具</li><li>找到并点击「Canvas Editor」标签页</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>编辑器实例可以通过以下方式暴露：</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 将编辑器实例挂载到 window 对象</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">window.__CANVAS_EDITOR_INSTANCE__ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> editor</span></span></code></pre></div></div>`,19)])])}const _=i(o,[["render",s]]);export{u as __pageData,_ as default};
